<template>
  <div class="page-container transformation-rules-page">
    <!-- Intro: transformation rules are a pipeline concept, so say what that
         means once. Doc type sits opposite, as on the layouts overview. -->
    <div class="page-head">
      <div class="page-intro">
        <h3 class="fb-title page-intro__title">
          {{ $t('transformation_rules') }}
          <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 6]">
            {{ $t('transformation_rules') }}
          </q-tooltip>
        </h3>
        <p class="page-intro__subtitle page-intro__subtitle--md">
          {{ $t('transformation_rules_intro') }}
          <b>{{ $t('routing_lowercase') }}</b>
          {{ $t('transformation_rules_intro_routing') }}
        </p>
      </div>

      <div v-if="doc_type_key" class="page-doctype">
        <Icon icon="mdi:file-document-outline" class="page-doctype__icon" />
        <span class="page-doctype__label">{{ $t('document_type') }}</span>
        <span class="page-doctype__value" data-test="doc-type">{{ doc_type_key }}</span>
      </div>
    </div>

    <!-- Toolbar — search top-left, scope filter + New rule pushed right
         (app-wide list pattern, same as the validation-rules list). -->
    <div class="flex items-center gap-2 q-mb-md">
      <q-input
        class="list-search"
        outlined dense
        debounce="300"
        color="primary"
        v-model="search"
        data-test="transformation-rule-search"
        :label="$t('search_by_column')"
      >
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-btn-toggle
        v-model="scopeFilter"
        no-caps unelevated
        toggle-color="primary"
        class="list-filter-toggle"
        data-test="tr-scope-filter"
        :options="scopeFilterOptions"
      />
      <q-btn-toggle
        v-model="statusFilter"
        no-caps unelevated
        toggle-color="primary"
        class="list-filter-toggle"
        data-test="tr-status-filter"
        :options="statusFilterOptions"
      />
      <q-space />
      <f-btn color="primary" icon="add" :label="$t('new_rule')" data-test="new-transformation-rule" @click="createRule" />
    </div>

    <Loader v-if="loading" />

    <!-- Empty states: nothing configured at all vs. nothing matching. -->
    <div v-else-if="!orderedRules.length" class="rule-empty" data-test="tr-empty">
      <!-- Iconify icon → the global <Icon> component; q-icon cannot resolve an
           `mdi:` name and would render nothing. -->
      <Icon icon="mdi:swap-horizontal-variant" height="34" width="34" class="rule-empty__icon" />
      <div class="rule-empty__title">{{ $t('no_transformation_rules_yet') }}</div>
      <div class="rule-empty__hint">{{ $t('no_transformation_rules_hint') }}</div>
      <f-btn color="primary" icon="add" :label="$t('new_rule')" class="q-mt-md" @click="createRule" />
    </div>
    <div v-else-if="!visibleRules.length" class="rule-empty" data-test="tr-no-match">
      {{ $t('no_rules_match') }}
    </div>

    <!-- Rule cards. Ordered by priority; the grip reorders (persisted as new
         priorities). Clicking anywhere else on the card opens the builder. -->
    <template v-else>
      <draggable
        class="rule-list height-100vh-285px"
        :list="orderedRules"
        item-key="id"
        handle=".tr-grip"
        :move="onDragMove"
        ghost-class="tr-rule--ghost"
        @change="onReorder"
      >
        <article
          v-for="({ rule, tokens }, idx) in decoratedRows"
          v-show="matchesFilters(decoratedRows[idx])"
          :key="rule.id"
          class="rule-card"
          :class="{ 'rule-card--off': !rule.is_active }"
          :data-test="'transformation-rule-' + rule.rule_key"
          tabindex="0"
          role="button"
          :aria-label="$t('edit_rule') + ': ' + rule.display_name"
          @click="editRule(rule)"
          @keydown.enter.prevent="editRule(rule)"
          @keydown.space.prevent="editRule(rule)"
        >
          <!-- Rank + drag handle -->
          <div class="tr-rank">
            <span class="tr-num">{{ idx + 1 }}</span>
            <span
              class="tr-grip"
              :aria-label="$t('reorder')"
              @click.stop
            >
              <img src="/icons/drag-grip.svg" class="tr-grip-icon" alt="" />
              <q-tooltip>{{ $t('drag_to_change_rule_order') }}</q-tooltip>
            </span>
          </div>

          <!-- Name, plain-English sentence, chips -->
          <div class="rule-card__body">
            <div class="item-name">{{ rule.display_name || $t('untitled_rule') }}</div>
            <div class="rule-card__desc tr-sentence">
              <template v-for="(tk, ti) in tokens" :key="ti">
                <span v-if="tk.kind === 'field'" class="tr-fld">{{ tk.text }}</span>
                <span v-else-if="tk.kind === 'cond'" class="tr-cnd">{{ tk.text }}</span>
                <b v-else-if="tk.kind === 'strong'">{{ tk.text }}</b>
                <span v-else>{{ tk.text }}</span>
              </template>
            </div>
            <div class="rule-card__meta">
              <q-badge :color="scopeMeta(rule.scope).color" :label="$t(scopeMeta(rule.scope).labelKey)" />
              <q-badge color="grey" :label="stepsLabel(rule)" />
              <q-badge
                :color="badgeMeta(rule.source_badge).color"
                :label="sourceLabel(rule.source_badge)"
              />
              <span v-if="rule.log_execution" class="rule-flag" data-test="tr-log-flag">
                <q-icon name="history" size="14px" />
                {{ $t('log_execution') }}
              </span>
            </div>
          </div>

          <!-- Activity (who last touched it), toggle, actions. A system
               default has no meaningful actor, so it shows a dash. -->
          <div class="rule-card__right">
            <div v-if="activityInfo(rule)" class="activity" data-test="tr-activity">
              <q-avatar class="activity__avatar" size="32px" color="primary" text-color="white">
                {{ activityInfo(rule).initials }}
              </q-avatar>
              <div class="activity__text">
                <span class="activity__name">{{ activityInfo(rule).name }}</span>
                <span class="activity__date">{{ formatTimeAgo(activityInfo(rule).dateIso) }}</span>
              </div>
              <q-tooltip
                v-if="formatTimestamp(activityInfo(rule).dateIso)"
                data-test="tr-activity-timestamp"
              >
                {{ formatTimestamp(activityInfo(rule).dateIso) }}
              </q-tooltip>
            </div>
            <span v-else class="activity__empty">—</span>
            <span class="rule-card__toggle" @click.stop>
              <f-toggle
                size="xs"
                :model-value="rule.is_active"
                :disable="togglingIds.includes(rule.id)"
                :data-test="'toggle-transformation-rule-' + rule.id"
                @update:model-value="(val: boolean) => toggleActive(rule, val)"
              />
              <q-spinner v-if="togglingIds.includes(rule.id)" size="14px" class="q-ml-xs" />
            </span>
            <RowActionsMenu
              :actions="rowActions"
              :row="rule"
              @action="onRuleAction(rule, $event)"
            />
          </div>
        </article>
      </draggable>

      <!-- Origin legend — the three badge colours are not self-evident, so name
           them once. A colour swatch (not a second badge) carries the colour, so
           the row reads as one label instead of repeating the badge text. -->
      <div class="tr-legend">
        <span v-for="item in legend" :key="item.badge">
          <q-badge class="tr-swatch" :color="item.color" />
          {{ $t(item.labelKey) }}
        </span>
      </div>
    </template>

    <!-- Delete / reset confirmations — the shared dialog, same as the layout
         selection-rules panel uses. Resetting deletes the org override so the
         underlying system default takes over again. -->
    <ConfirmDialog
      v-model="deleteDialog"
      :message="$t('confirm_delete_transformation_rule')"
      :confirm-label="$t('delete')"
      :cancel-label="$t('cancel')"
      confirm-color="negative"
      @confirm="confirmDelete"
    />

    <ConfirmDialog
      v-model="resetDialog"
      :message="$t('reset_to_default_confirm')"
      :confirm-label="$t('reset_to_default')"
      :cancel-label="$t('cancel')"
      confirm-color="negative"
      @confirm="confirmReset"
    />

  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { notify, notifyApiError } from 'src/components/notifications/notify';
import { useFormattedTimeAgo, useFormattedTimestamp } from 'src/boot/timeago';
import { transformationRulesApiService } from 'src/services';
import { useTrListFiltersStore } from 'src/store/Settings/tr-list-filters.store';
import type { TrListFilters, TrStatusFilter } from 'src/store/Settings/tr-list-filters.store';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import Loader from 'src/components/Loader.vue';
import RowActionsMenu from 'src/components/Table/RowActionsMenu.vue';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
import { VueDraggableNext } from 'vue-draggable-next';
import type { RowActionItem } from 'src/components/Table/types/table/unified-table';
import {
  ruleSentence,
  sentenceText,
  shortFieldName,
  slugify,
  SCOPE_META,
  SCOPE_ORDER,
  BADGE_META,
  BADGE_ORDER,
  type SentenceToken,
} from './transformation-rule-model';
import { conditionPhrases } from './condition-phrases';
import type {
  TransformationRule,
  TransformationRuleScope,
  TransformationRuleSourceBadge,
} from 'src/services/settings/TransformationRulesApiService';

export default defineComponent({
  name: 'TransformationRulesList',
  components: { Loader, RowActionsMenu, ConfirmDialog, draggable: VueDraggableNext },
  data() {
    return {
      doc_type_key: '',
      // Free-text search above the list (name / target / action types).
      search: '',
      // Scope toggle above the list: 'all' | 'header' | 'column' | 'document'.
      scopeFilter: 'all' as 'all' | TransformationRuleScope,
      // Status toggle: 'all' | 'active' | 'inactive' (filters is_active).
      statusFilter: 'all' as TrStatusFilter,
      // Actions depend on the rule's origin — same contract as the validation
      // rules list: a system default offers Customize (fork into an editable org
      // copy), an org rule offers Edit. Duplicate is always available. The last
      // slot is Reset to Default (an override) or Delete (a from-scratch rule);
      // a system default has neither (it cannot be removed).
      rowActions: [
        { key: 'customize', label: 'customize', icon: 'tune', color: 'primary', show: (row: TransformationRule) => this.isDefaultRule(row) },
        { key: 'edit', label: 'edit', icon: 'edit', color: 'primary', show: (row: TransformationRule) => !this.isDefaultRule(row) },
        { key: 'duplicate', label: 'duplicate', icon: 'content_copy', color: 'primary' },
        { key: 'reset', label: 'reset_to_default', icon: 'restore', color: 'negative', separator: true, show: (row: TransformationRule) => row.source_badge === 'customized' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true, show: (row: TransformationRule) => row.source_badge === 'custom' },
      ] as RowActionItem[],
    };
  },
  computed: {
    scopeFilterOptions(): { label: string; value: 'all' | TransformationRuleScope }[] {
      return [
        { label: this.$t('all'), value: 'all' },
        ...SCOPE_ORDER.map((scope) => ({
          label: this.$t(SCOPE_META[scope].labelKey),
          value: scope,
        })),
      ];
    },
    statusFilterOptions(): { label: string; value: TrStatusFilter }[] {
      return [
        { label: this.$t('all'), value: 'all' },
        { label: this.$t('active'), value: 'active' },
        { label: this.$t('inactive'), value: 'inactive' },
      ];
    },
    // Origin legend rows, straight off the shared badge table.
    legend(): { badge: string; color: string; labelKey: string }[] {
      return BADGE_ORDER.map((badge) => ({
        badge,
        color: BADGE_META[badge].color,
        // The legend spells out what each origin means; the badge itself only
        // shows the short name.
        labelKey: {
          system_default: 'system_default',
          customized: 'customised_overrides_a_default',
          custom: 'custom_this_organisation',
        }[badge],
      }));
    },
    // Bundle the toolbar filters so a single watcher can persist them.
    filterState(): TrListFilters {
      return {
        search: this.search,
        scopeFilter: this.scopeFilter,
        statusFilter: this.statusFilter,
      };
    },
    // True while a filter hides rows — dragging is blocked then, because an
    // index swap across hidden rows would be meaningless.
    isFiltering(): boolean {
      return (
        !!this.search.trim() || this.scopeFilter !== 'all' || this.statusFilter !== 'all'
      );
    },
    // Each row with its generated sentence and a pre-lowercased search haystack,
    // built ONCE per data change. The sentence is expensive (a tree walk plus a
    // translate call per operator and per action), and the template needs it for
    // display while the filter needs it as text — computing it here keeps both
    // off the render path.
    decoratedRows(): { rule: TransformationRule; tokens: SentenceToken[]; haystack: string }[] {
      return this.orderedRules.map((rule: TransformationRule) => {
        const tokens = this.sentenceFor(rule);
        return {
          rule,
          tokens,
          haystack: [
            rule.display_name,
            rule.description || '',
            rule.target_field,
            shortFieldName(rule.source || ''),
            (rule.actions || []).map((a) => a.type).join(' '),
            this.$t(SCOPE_META[rule.scope]?.labelKey || rule.scope),
            this.sourceLabel(rule.source_badge),
            sentenceText(tokens),
          ]
            .join(' ')
            .toLowerCase(),
        };
      });
    },
    // Rows that survive the toolbar filters — used to pick between the two empty
    // states. The cards themselves render from decoratedRows with v-show so drag
    // indices stay stable.
    visibleRules(): TransformationRule[] {
      return this.decoratedRows.filter((row) => this.matchesFilters(row)).map((row) => row.rule);
    },
  },
  watch: {
    // Persist the toolbar filters so they survive navigating into a rule and
    // back (and are restored on mount). Keyed to the current doc type.
    filterState: {
      deep: true,
      handler(state: TrListFilters) {
        this.trFilters.setFilters(this.doc_type_key, state);
      },
    },
  },
  mounted() {
    this.doc_type_key = String(this.$route.params.doc_type || '');
    const saved = this.trFilters.filtersFor(this.doc_type_key);
    this.search = saved.search;
    this.scopeFilter = saved.scopeFilter;
    this.statusFilter = saved.statusFilter;
    this.loadSubOrgs();
    this.loadRules();
  },
  methods: {
    async loadRules() {
      if (!this.doc_type_key) {
        return;
      }
      try {
        this.loading = true;
        const resp = await transformationRulesApiService.list(this.doc_type_key);
        this.orderedRules = this.sortByPriority(Array.isArray(resp) ? resp : []);
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    // Rules run in ascending priority; ties keep a stable, name-based order so
    // the list doesn't shuffle between loads.
    sortByPriority(list: TransformationRule[]): TransformationRule[] {
      return list.slice().sort((a, b) => {
        const byPriority = (Number(a.priority) || 0) - (Number(b.priority) || 0);
        return byPriority !== 0 ? byPriority : a.display_name.localeCompare(b.display_name);
      });
    },
    // Sub-organisation names for routing-rule sentences (`set_value` stores the
    // sub-org id). Same shared dropdown store the builder uses.
    async loadSubOrgs() {
      try {
        // The store already indexes id → name (subOrgMap) in the same pass, so
        // just make sure it is populated; getSubOrgName reads that map.
        await this.dropdowns.getSubOrgsList();
      } catch (err) {
        logError(err);
      }
    },
    // The plain-English summary for one rule, as render tokens.
    sentenceFor(rule: TransformationRule): SentenceToken[] {
      const aw = rule.applies_when || {};
      const join: 'all' | 'any' = Array.isArray(aw.any) ? 'any' : 'all';
      return ruleSentence(
        {
          scope: rule.scope,
          target_field: rule.target_field,
          source: rule.source || '',
          actions: rule.actions || [],
          conditions: conditionPhrases(aw, join, this.$t),
          join,
        },
        this.doc_type_key,
        this.$t,
        (value: string) => this.dropdowns.getSubOrgName(value) || value,
      );
    },
    // Scope toggle + free-text search against the row's precomputed haystack
    // (everything the user can see on the card, including the sentence).
    matchesFilters(row: { rule: TransformationRule; haystack: string }): boolean {
      if (this.scopeFilter !== 'all' && row.rule.scope !== this.scopeFilter) {
        return false;
      }
      if (this.statusFilter === 'active' && !row.rule.is_active) {
        return false;
      }
      if (this.statusFilter === 'inactive' && row.rule.is_active) {
        return false;
      }
      const q = this.search.trim().toLowerCase();
      return !q || row.haystack.includes(q);
    },
    // Block drops while filtering (rows are hidden, so an index swap would be
    // meaningless). Returning false cancels the move.
    onDragMove(): boolean {
      return !this.isFiltering;
    },
    // Drag finished — draggable already reordered orderedRules in place. Assign
    // ascending priorities in the new visual order and persist ONLY the rules
    // whose priority actually changed. Reverts from the server on failure.
    //
    // Note: the backend forks a system default into an org override on any
    // mutation (same as the toggle), so reordering a default customises it.
    async onReorder() {
      const changed = this.orderedRules.filter(
        (r: TransformationRule, i: number) => Number(r.priority) !== i,
      );
      if (!changed.length) {
        return;
      }
      this.orderedRules.forEach((r: TransformationRule, i: number) => {
        r.priority = i;
      });
      try {
        await Promise.all(
          changed.map((r: TransformationRule) =>
            transformationRulesApiService.update(r.id, {
              display_name: r.display_name,
              description: r.description,
              target_field: r.target_field,
              source: r.source,
              table_name: r.table_name,
              applies_when: r.applies_when,
              actions: r.actions,
              priority: r.priority,
              is_active: r.is_active,
              log_execution: r.log_execution,
            }),
          ),
        );
        notify.success(this.$t('MSG_SAVE'));
        // Re-read so forked defaults come back with their new ids/badges.
        await this.loadRules();
      } catch (err) {
        notifyApiError(err);
        logError(err);
        await this.loadRules();
      }
    },
    async toggleActive(row: TransformationRule, val: boolean) {
      if (this.togglingIds.includes(row.id)) {
        return;
      }
      const previous = row.is_active;
      // Optimistic update — flip immediately, revert if the call fails.
      row.is_active = val;
      this.togglingIds.push(row.id);
      try {
        const updated = await transformationRulesApiService.setActive(row.id, val);
        // Toggling a system default forks it into an org override with a NEW id,
        // so re-read the list rather than trusting the local row.
        if (updated && updated.id && updated.id !== row.id) {
          await this.loadRules();
        }
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        row.is_active = previous;
        notifyApiError(err);
        logError(err);
      } finally {
        this.togglingIds = this.togglingIds.filter((id) => id !== row.id);
      }
    },
    // Seeded system rules carry source_badge === 'system_default'.
    isDefaultRule(row: TransformationRule): boolean {
      return row.source_badge === 'system_default';
    },
    // Initials for the activity avatar — same rule as the validation-rules
    // list and the header User Dropdown: first + last initial (one name → one
    // letter).
    getInitials(fullname: string): string {
      const names = (fullname || '').trim().split(/\s+/);
      let initials = names[0].substring(0, 1).toUpperCase();
      if (names.length > 1) {
        initials += names[names.length - 1].substring(0, 1).toUpperCase();
      }
      return initials;
    },
    // The rule's latest audit touch: last-modified if a name is recorded, else
    // created. Seeded system defaults have no meaningful actor, so they show
    // none — even when the backend stamps one on them.
    activityInfo(
      row: TransformationRule,
    ): { name: string; initials: string; dateIso: string } | null {
      if (this.isDefaultRule(row)) {
        return null;
      }
      if (row.last_modified_by_name) {
        return {
          name: row.last_modified_by_name,
          initials: this.getInitials(row.last_modified_by_name),
          dateIso: row.last_modified_on || '',
        };
      }
      if (row.created_by_name) {
        return {
          name: row.created_by_name,
          initials: this.getInitials(row.created_by_name),
          dateIso: row.created_on || '',
        };
      }
      return null;
    },
    // How many steps the pipeline runs, as a badge label.
    stepsLabel(row: TransformationRule): string {
      const n = (row.actions || []).length;
      return n === 1 ? this.$t('one_step') : this.$t('n_steps', { count: n });
    },
    // Colour + label for a scope / origin badge, from the shared tables. An
    // unrecognised value from the server degrades to a grey pill rather than
    // rendering nothing.
    scopeMeta(scope: TransformationRuleScope): { color: string; labelKey: string } {
      return SCOPE_META[scope] || { color: 'grey', labelKey: scope };
    },
    badgeMeta(badge: TransformationRuleSourceBadge): { color: string; labelKey: string } {
      return BADGE_META[badge] || { color: 'grey', labelKey: badge };
    },
    // Translated origin label; an unexpected value falls back to a humanized
    // form of the raw string so it still reads sensibly.
    sourceLabel(badge: TransformationRuleSourceBadge): string {
      if (!badge) {
        return '';
      }
      if (BADGE_META[badge]) {
        return this.$t(BADGE_META[badge].labelKey);
      }
      return String(badge)
        .split('_')
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
    },
    createRule() {
      this.$router.push(
        '/settings/transformation-rules/' + this.doc_type_key + '/new',
      );
    },
    onRuleAction(row: TransformationRule, action: string) {
      if (action === 'customize') {
        this.customizeRule(row);
      } else if (action === 'edit') {
        this.editRule(row);
      } else if (action === 'duplicate') {
        this.duplicateRule(row);
      } else if (action === 'reset') {
        this.onReset(row);
      } else if (action === 'delete') {
        this.onDelete(row);
      }
    },
    editRule(row: TransformationRule) {
      if (!row || !row.id) {
        return;
      }
      // Hand the full row to the builder via router state so edit mode prefills
      // without an extra fetch (falls back to get-by-id on refresh).
      this.$router.push({
        path:
          '/settings/transformation-rules/' + this.doc_type_key + '/' + row.id,
        state: { rule: JSON.parse(JSON.stringify(row)) },
      });
    },
    // Customize a system default: ask the backend for an editable org copy (a
    // new rule with the same rule_key), then open it in the builder.
    async customizeRule(row: TransformationRule) {
      if (!row || !row.id) {
        return;
      }
      try {
        const override = await transformationRulesApiService.customize(row.id);
        this.$router.push({
          path: '/settings/transformation-rules/' + this.doc_type_key + '/' + override.id,
          state: { rule: JSON.parse(JSON.stringify(override)) },
        });
      } catch (err) {
        notifyApiError(err);
        logError(err);
      }
    },
    // Duplicate a rule: the backend clones the full definition off the source
    // rule, so only the new row's identity is sent — " - Copy" appended to the
    // name plus a matching fresh rule_key. Works for system defaults too; the
    // copy is created as a custom rule.
    async duplicateRule(row: TransformationRule) {
      if (!row || !row.id) {
        return;
      }
      const display_name = `${row.display_name} - Copy`;
      try {
        await transformationRulesApiService.clone(row.id, {
          rule_key: slugify(display_name),
          display_name,
        });
        notify.success(this.$t('MSG_SAVE'));
        await this.loadRules();
      } catch (err) {
        notifyApiError(err);
        logError(err);
      }
    },
    // A system default is backend-managed and cannot be deleted.
    onDelete(row: TransformationRule) {
      if (this.isDefaultRule(row)) {
        return;
      }
      this.ruleToDelete = row;
      this.deleteDialog = true;
    },
    async confirmDelete() {
      const row = this.ruleToDelete;
      if (!row) {
        return;
      }
      try {
        await transformationRulesApiService.deleteTransformationRule(row.id);
        notify.success(this.$t('MSG_DELETE'));
        await this.loadRules();
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.ruleToDelete = null;
      }
    },
    // Reset a customized rule back to its system default: deleting the org
    // override makes the backend re-expose the underlying default.
    onReset(row: TransformationRule) {
      this.ruleToReset = row;
      this.resetDialog = true;
    },
    async confirmReset() {
      const row = this.ruleToReset;
      if (!row) {
        return;
      }
      try {
        await transformationRulesApiService.deleteTransformationRule(row.id);
        notify.success(this.$t('reset_to_default_success'));
        await this.loadRules();
      } catch (err) {
        notifyApiError(err);
        logError(err);
      } finally {
        this.ruleToReset = null;
      }
    },
  },
  setup() {
    return {
      trFilters: useTrListFiltersStore(),
      dropdowns: useDropdownStore(),
      formatTimeAgo: useFormattedTimeAgo,
      formatTimestamp: useFormattedTimestamp,
      // The priority-ordered view the draggable mutates in place.
      orderedRules: ref([] as TransformationRule[]),
      loading: ref(false),
      togglingIds: ref([] as string[]),
      deleteDialog: ref(false),
      ruleToDelete: ref<TransformationRule | null>(null),
      resetDialog: ref(false),
      ruleToReset: ref<TransformationRule | null>(null),
    };
  },
});
</script>

