import { defineStore } from 'pinia';
import type { TransformationRuleScope } from 'src/services/settings/TransformationRulesApiService';

type TrScopeFilter = 'all' | TransformationRuleScope;
export type TrStatusFilter = 'all' | 'active' | 'inactive';

export interface TrListFilters {
  search: string;
  scopeFilter: TrScopeFilter;
  statusFilter: TrStatusFilter;
}

function emptyFilters(): TrListFilters {
  return { search: '', scopeFilter: 'all', statusFilter: 'all' };
}

// Toolbar filter state for the Transformation Rules list, so search + the
// scope/status toggles survive navigating into a rule and back. Scoped to one
// doc type. Mirrors cvr-list-filters.store.
export const useTrListFiltersStore = defineStore('tr_list_filters', {
  state: () => ({
    docTypeKey: '',
    filters: emptyFilters(),
  }),

  actions: {
    filtersFor(docTypeKey: string): TrListFilters {
      if (this.docTypeKey !== docTypeKey) {
        this.docTypeKey = docTypeKey;
        this.filters = emptyFilters();
      }
      return this.filters;
    },

    setFilters(docTypeKey: string, filters: TrListFilters) {
      this.docTypeKey = docTypeKey;
      this.filters = { ...filters };
    },
  },
});
